  13|// MaxConstraintGateRetries is the maximum number of times the orchestrator will
  14|// retry a constraint gate failure before failing the task.
  15|const MaxConstraintGateRetries = 5
  16|
  17|// constraintGateBaseDelay is the base delay for exponential backoff between
  18|// constraint gate retry attempts.
  19|const constraintGateBaseDelay = 30 * time.Second
  20|
  21|// ConstraintGatePolicy encapsulates backoff, retry cap, and early-termination
  22|// logic for constraint gate retries. Delay grows exponentially with jitter:
  23|// baseDelay * 2^(attempt-1) * (1 + rand[0,0.5)), capped at maxDelay.
  24|type ConstraintGatePolicy struct {
  25|	MaxRetries int
  26|	BaseDelay  time.Duration
  27|	MaxDelay   time.Duration
  28|}
  29|
  30|// ConstraintFailure describes a single constraint that failed evaluation.
  31|type ConstraintFailure struct {
  32|	Name    string
  33|	Current string
  34|	Limit   string
  35|}
  36|
  37|// DefaultConstraintGatePolicy returns the standard retry policy for constraint
  38|// gate operations.
  39|func DefaultConstraintGatePolicy() ConstraintGatePolicy {
  40|	return ConstraintGatePolicy{
  41|		MaxRetries: MaxConstraintGateRetries,
  42|		BaseDelay:  constraintGateBaseDelay,
  43|		MaxDelay:   10 * time.Minute,
  44|	}
  45|}
  46|
  47|// Delay returns the backoff duration for the given attempt number (1-based),
  48|// including random jitter.
  49|func (p ConstraintGatePolicy) Delay(attempt int) time.Duration {
  50|	if attempt < 1 {
  51|		attempt = 1
  52|	}
  53|	d := p.BaseDelay
  54|	for i := 1; i < attempt; i++ {
  55|		d *= 2
  56|	}
  57|	if p.MaxDelay > 0 && d > p.MaxDelay {
  58|		d = p.MaxDelay
  59|	}
  60|	// Add jitter: multiply by (1 + rand[0, 0.5))
  61|	jitter := time.Duration(rand.Float64() * 0.5 * float64(d))
  62|	return d + jitter
  63|}
  64|
  65|// Exhausted returns true if the attempt count has reached or exceeded MaxRetries.
  66|func (p ConstraintGatePolicy) Exhausted(attempt int) bool {
  67|	return attempt >= p.MaxRetries
  68|}
  69|
  70|// ShouldTerminateEarly returns true when the current per-constraint comparison
  71|// shows no improvement over the previous attempt, indicating retries are
  72|// unlikely to help. Returns false when previous.Dominated is false, meaning
  73|// this is the first blocked evaluation and there is no prior baseline.
  74|func (p ConstraintGatePolicy) ShouldTerminateEarly(current, previous constraints.ComparisonResult) bool {
  75|	// No prior dominated result — first blocked attempt, do not terminate.
  76|	if !previous.Dominated {
  77|		return false
  78|	}
  79|	// Terminate if the number of blocking constraints has not decreased.
  80|	return current.Magnitude() >= previous.Magnitude()
  81|}
  82|
  83|// FormatConstraintFailure produces a structured failure message listing each
  84|// failed constraint with its current value, limit, and the attempt context.
  85|func FormatConstraintFailure(failures []ConstraintFailure, attempt, maxRetries int) string {
  86|	var b strings.Builder
  87|	fmt.Fprintf(&b, "constraint gate failed (attempt %d/%d)", attempt, maxRetries)
  88|	if len(failures) == 0 {
  89|		return b.String()
  90|	}
  91|	b.WriteString(":\n")
  92|	for _, f := range failures {
  93|		fmt.Fprintf(&b, "  - %s: current=%s, limit=%s\n", f.Name, f.Current, f.Limit)
  94|	}
  95|	return b.String()
